  let n=0;
  Object.entries(patch).forEach(([t,ps])=>{ if(TEAMS[t]){TEAMS[t].players=ps;n++;} });
  console.log('[WC2026] '+n+' teams updated');

  // Sync updated photos from squad_patch into ORIGINAL_LINEUPS (match panel uses these)
  // This ensures groups view + calendar match panel show the same player photos
  if (typeof ORIGINAL_LINEUPS !== 'undefined') {
    Object.entries(TEAMS).forEach(([teamName, td]) => {
      const origPool = ORIGINAL_LINEUPS[teamName];
      if (!origPool || !td.players) return;
      const photoMap = {};
      td.players.forEach(p => { if (p.id && p.photo) photoMap[p.id] = p.photo; });
      origPool.forEach(p => { if (p.id && photoMap[p.id]) p.photo = photoMap[p.id]; });
    });
    console.log('[WC2026] ORIGINAL_LINEUPS photos synced');
  }
